style.css:
@-moz-document domain("youtube.com"), domain("youtube-nocookie.com") {
/* ===== ОСНОВНЫЕ ПЕРЕМЕННЫЕ ===== */
  :root, html[dark], [dark] {
    --yt-spec-base-background: #0a1410 !important;
    --yt-spec-raised-background: #0f1e18 !important;
    --yt-spec-menu-background: #12261e !important;
    --yt-spec-general-background-a: #0d1a15 !important;
    --yt-spec-general-background-b: #0a1410 !important;
    --yt-spec-general-background-c: #08110d !important;
    --yt-spec-brand-background-primary: #0f1e18 !important;
    --yt-spec-brand-background-solid: #0f1e18 !important;
    --yt-spec-text-primary: #d9f5e6 !important;
    --yt-spec-text-secondary: #8fbfa8 !important;
    --yt-spec-icon-inactive: #9fd4b8 !important;
    --yt-spec-icon-active-other: #b8f0d2 !important;
    --yt-spec-call-to-action: #2ecc71 !important;
    --yt-spec-badge-chip-background: #17362a !important;
    --yt-spec-10-percent-layer: rgba(46, 204, 113, 0.1) !important;
    --yt-spec-brand-link-text: #4ade80 !important;
    --yt-spec-themed-blue: #34d399 !important;
    --yt-spec-themed-green: #22c55e !important;
  }

  /* ===== ФОН ===== */
  html, body, ytd-app, #content, #page-manager {
    background: #0a1410 !important;
  }

  /* Шапка */
  ytd-masthead, #masthead-container, #container.ytd-masthead {
    background: linear-gradient(180deg, #0f1e18 0%, #0a1410 100%) !important;
    border-bottom: 1px solid rgba(46, 204, 113, 0.15) !important;
    backdrop-filter: blur(12px);
  }

  /* Поисковая строка */
  #search-form, ytd-searchbox #container,
  .ytd-searchbox, #search {
    background: #12261e !important;
    border: 1px solid rgba(46, 204, 113, 0.25) !important;
    border-radius: 12px !important;
    transition: all 0.25s ease !important;
  }

  ytd-searchbox[has-focus] #container {
    border-color: #2ecc71 !important;
    box-shadow: 0 0 0 3px rgba(46, 204, 113, 0.2) !important;
  }

  #search-icon-legacy, .search-button {
    background: #17362a !important;
    border-color: rgba(46, 204, 113, 0.3) !important;
  }

  /* Боковая панель */
  ytd-guide-renderer, #guide-content, #guide-wrapper {
    background: #0d1a15 !important;
    border-right: 1px solid rgba(46, 204, 113, 0.1) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: rgba(46, 204, 113, 0.12) !important;
    border-radius: 10px !important;
  }

  ytd-guide-entry-renderer[active] {
    background: rgba(46, 204, 113, 0.18) !important;
    border-left: 3px solid #2ecc71 !important;
    border-radius: 0 10px 10px 0 !important;
  }

  /* ===== ВИДЕО КАРТОЧКИ ===== */
  ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer {
    background: transparent !important;
    transition: transform 0.25s ease, filter 0.25s ease !important;
  }

  ytd-rich-item-renderer:hover, ytd-video-renderer:hover {
    transform: translateY(-3px);
  }

  /* Миниатюры */
  ytd-thumbnail, ytd-rich-thumbnail, img.yt-img-shadow {
    border-radius: 12px !important;
    overflow: hidden !important;
  }

  ytd-thumbnail:hover {
    box-shadow: 0 8px 24px rgba(46, 204, 113, 0.25) !important;
  }

  /* Заголовки видео */
  #video-title, .ytd-video-meta-block #video-title {
    color: #d9f5e6 !important;
    font-weight: 500 !important;
  }

  #video-title:hover {
    color: #4ade80 !important;
  }

  /* Метаданные (просмотры, дата) */
  #metadata-line, .ytd-video-meta-block {
    color: #8fbfa8 !important;
  }

  /* Аватарки */
  yt-img-shadow#avatar img, #avatar-link img {
    border: 2px solid rgba(46, 204, 113, 0.3) !important;
  }

  /* ===== КНОПКИ ===== */
  ytd-button-renderer button,
  tp-yt-paper-button {
    border-radius: 20px !important;
    transition: all 0.2s ease !important;
  }

  /* Кнопка подписки */
  ytd-subscribe-button-renderer tp-yt-paper-button[filled] {
    background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%) !important;
    color: #0a1410 !important;
    font-weight: 600 !important;
    box-shadow: 0 0 20px rgba(34, 197, 94, 0.35) !important;
  }

  ytd-subscribe-button-renderer tp-yt-paper-button[filled]:hover {
    box-shadow: 0 0 30px rgba(34, 197, 94, 0.55) !important;
    transform: scale(1.03);
  }

  /* Кнопки лайк/дизлайк/шер */
  ytd-toggle-button-renderer button,
  #top-level-buttons-computed ytd-button-renderer button {
    background: #17362a !important;
    color: #b8f0d2 !important;
  }

  ytd-toggle-button-renderer button:hover,
  #top-level-buttons-computed ytd-button-renderer button:hover {
    background: #1f4a38 !important;
    color: #4ade80 !important;
  }

  /* Активный лайк */
  ytd-toggle-button-renderer[is-icon-button] button[aria-pressed="true"] {
    color: #22c55e !important;
  }

  /* ===== ВИДЕОПЛЕЕР ===== */
  #movie_player, .html5-video-player {
    background: #000 !important;
  }

  /* Прогресс-бар (красная полоса → зелёная) */
  .ytp-play-progress, .ytp-scrubber-button {
    background: #22c55e !important;
  }

  .ytp-load-progress {
    background: rgba(46, 204, 113, 0.4) !important;
  }

  .ytp-scrubber-button {
    box-shadow: 0 0 10px rgba(34, 197, 94, 0.8) !important;
  }

  /* Плеер-контролы */
  .ytp-chrome-bottom .ytp-chrome-controls {
    background: linear-gradient(transparent, rgba(10, 20, 16, 0.9)) !important;
  }

  /* ===== КОММЕНТАРИИ ===== */
  ytd-comment-thread-renderer, ytd-comment-renderer {
    background: transparent !important;
  }

  #content-text, yt-formatted-string#content-text {
    color: #c8e6d4 !important;
  }

  #author-text, .ytd-comment-renderer #author-text {
    color: #4ade80 !important;
    font-weight: 600 !important;
  }

  /* Поле ввода комментария */
  #simple-box, ytd-comment-simplebox-renderer #placeholder-area {
    background: #12261e !important;
    border: 1px solid rgba(46, 204, 113, 0.25) !important;
    border-radius: 12px !important;
  }

  /* ===== ЧИПЫ / ТЕГИ ===== */
  ytd-chip-cloud-chip-renderer, .yt-chip-cloud-chip {
    background: #17362a !important;
    color: #b8f0d2 !important;
    border: 1px solid rgba(46, 204, 113, 0.2) !important;
  }

  ytd-chip-cloud-chip-renderer[selected] {
    background: linear-gradient(135deg, #22c55e, #16a34a) !important;
    color: #0a1410 !important;
    font-weight: 600 !important;
  }

  /* ===== СКРОЛЛБАР ===== */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0a1410;
  }

  ::-webkit-scrollbar-thumb {
    background: #1f4a38;
    border-radius: 10px;
    border: 2px solid #0a1410;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #2ecc71;
  }

  /* ===== САЙДБАР ВИДЕО (похожие) ===== */
  ytd-compact-video-renderer:hover {
    background: rgba(46, 204, 113, 0.06) !important;
    border-radius: 10px !important;
  }

  /* ===== МЕНЮ / ПОПАПЫ ===== */
  tp-yt-paper-listbox, ytd-menu-popup-renderer,
  .ytd-multi-page-menu-renderer {
    background: #12261e !important;
    border: 1px solid rgba(46, 204, 113, 0.2) !important;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6) !important;
  }

  tp-yt-paper-item:hover {
    background: rgba(46, 204, 113, 0.12) !important;
  }

  /* ===== АНИМАЦИЯ ПРИ НАВЕДЕНИИ НА ЛОГОТИП ===== */
  ytd-logo:hover svg {
    filter: drop-shadow(0 0 8px rgba(46, 204, 113, 0.8));
  }

  /* ===== ПЛЕЙЛИСТЫ / РАЗДЕЛЫ ===== */
  ytd-playlist-video-renderer:hover {
    background: rgba(46, 204, 113, 0.08) !important;
  }

  ytd-playlist-panel-renderer {
    background: #0d1a15 !important;
    border-left: 1px solid rgba(46, 204, 113, 0.15) !important;
  }

  /* Активное видео в плейлисте */
  ytd-playlist-panel-video-renderer[selected] {
    background: rgba(46, 204, 113, 0.15) !important;
    border-left: 3px solid #2ecc71 !important;
  }

  /* ===== ЛАЙВ-БЕЙДЖИ, ПРЕМЬЕРА ===== */
  .badge-style-type-live-now,
  .ytd-badge-supported-renderer .badge {
    background: #22c55e !important;
    color: #0a1410 !important;
    font-weight: 700 !important;
  }
}
